	try {
		eval("fsp_fn_notLogin();");
	} catch( e ) {
		alert( "세션이 종료되었습니다. 다시 로그인해주세요." );
		
		try {
			if( opener ) {
				opener.parent.window.location = "/view/login.jsp";
				self.close();
			}
		} catch ( ee ) {
			window.location = "/view/login.jsp";
		}
	}	
};

